<script lang="ts">
 import {onMount} from 'svelte';import type {Snippet} from 'svelte';let {children,onclose}:{children:Snippet;onclose:()=>void}=$props();let panel:HTMLDivElement;
 onMount(()=>{const previous=document.activeElement as HTMLElement;const shell=document.querySelector<HTMLElement>('.app-shell');if(shell)shell.inert=true;panel.focus();const keys=(e:KeyboardEvent)=>{if(e.isComposing)return;if(e.key==='Escape'){e.preventDefault();onclose()}if(e.key==='Tab'){const nodes=Array.from(panel.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,a[href]')).filter(n=>n.getClientRects().length);if(e.shiftKey&&(document.activeElement===nodes[0]||document.activeElement===panel)){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}};document.addEventListener('keydown',keys);return()=>{if(shell)shell.inert=false;document.removeEventListener('keydown',keys);previous?.isConnected&&previous.focus({preventScroll:true})}});
</script>
<div class="navigation-shade" role="presentation" onclick={e=>{if(e.target===e.currentTarget)onclose()}}><div class="navigation-drawer" role="dialog" aria-modal="true" aria-label="导航" tabindex="-1" bind:this={panel}><button class="drawer-close" aria-label="关闭导航" onclick={onclose}>关闭</button>{@render children()}</div></div>
